BEGIN;
CREATE TABLE IF NOT EXISTS mission_bridge_mobile_worker_profiles(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,user_id TEXT NOT NULL,worker_type TEXT NOT NULL CHECK(worker_type IN('delivery','courier','ride_hailing','freight')),city_code TEXT NOT NULL,driving_mode BOOLEAN NOT NULL DEFAULT FALSE,updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(tenant_id,user_id));
CREATE TABLE IF NOT EXISTS mission_bridge_micro_audio(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,title TEXT NOT NULL,duration_minutes INTEGER NOT NULL CHECK(duration_minutes IN(3,5,7)),audio_url TEXT NOT NULL,transcript_content_id UUID REFERENCES mission_bridge_content_catalog(id),topic TEXT NOT NULL,published BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS mission_bridge_audio_progress(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,user_id TEXT NOT NULL,audio_id UUID NOT NULL REFERENCES mission_bridge_micro_audio(id),position_seconds INTEGER NOT NULL DEFAULT 0,completed BOOLEAN NOT NULL DEFAULT FALSE,updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(tenant_id,user_id,audio_id));
CREATE TABLE IF NOT EXISTS mission_bridge_callback_requests(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,user_id TEXT NOT NULL,preferred_window TEXT NOT NULL DEFAULT 'later',status TEXT NOT NULL DEFAULT 'requested',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS mission_bridge_city_program_assignments(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,user_id TEXT NOT NULL,city_code TEXT NOT NULL,program_id TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active',changed_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS mission_bridge_worker_station_events(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,city_code TEXT NOT NULL,station_name TEXT NOT NULL,title TEXT NOT NULL,event_time TIMESTAMPTZ,qr_token_hash TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'planned');
CREATE TABLE IF NOT EXISTS mission_bridge_async_worker_groups(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,city_code TEXT NOT NULL,time_window TEXT NOT NULL CHECK(time_window IN('late_night','afternoon','flexible')),title TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active');
DO $$ DECLARE t TEXT; BEGIN FOREACH t IN ARRAY ARRAY['mission_bridge_mobile_worker_profiles','mission_bridge_micro_audio','mission_bridge_audio_progress','mission_bridge_callback_requests','mission_bridge_city_program_assignments','mission_bridge_worker_station_events','mission_bridge_async_worker_groups'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY tenant_isolation ON %I USING (tenant_id=current_setting(''app.tenant_id'',true)) WITH CHECK (tenant_id=current_setting(''app.tenant_id'',true))',t);END LOOP;END $$;
COMMIT;
